import {supabase,currentUser,login,saveSettings,loadSettings} from './auth-client.mjs';
import {DOJO_ELEMENTS,emptyDojoLevels} from './account-model.mjs';
const $=id=>document.getElementById(id);let user=null,levels=emptyDojoLevels(),data,revision=0,loading=false;
const root=new URL('./tatari-data/',import.meta.url),el=(tag,value)=>{const n=document.createElement(tag);if(value!==undefined)n.textContent=value;return n;};
function badgePickers(){const holder=$('account-dojos');holder.replaceChildren();for(const [element,label] of DOJO_ELEMENTS){const group=el('section'),header=el('h3',label+' Dojo'),row=el('div');row.className='account-badge-row';const clear=el('button','None');clear.type='button';clear.setAttribute('aria-label','Clear '+label+' badges');clear.setAttribute('aria-pressed',String(levels[element]===0));clear.onclick=()=>{levels[element]=0;badgePickers();$('save-status').textContent='Unsaved changes';};row.append(clear);for(const [i,b] of data.badges.filter(b=>b.element===Number(element)).sort((a,b)=>a.id-b.id).entries()){const button=el('button'),img=el('img');button.type='button';img.src=new URL(b.image,root);img.alt=b.name;button.setAttribute('aria-label',label+' badge '+(i+1));button.setAttribute('aria-pressed',String(i<levels[element]));button.append(img,el('span',String.fromCharCode(65+i)));button.onclick=()=>{levels[element]=levels[element]===i+1?0:i+1;badgePickers();$('save-status').textContent='Unsaved changes';};row.append(button);}group.append(header,row);holder.append(group);}}
async function refresh(){if(!data)return;const id=++revision;try{user=await currentUser();if(id!==revision)return;$('signed-out').hidden=!!user;$('signed-in').hidden=!user;if(!user)return;$('profile-name').value=user.user_metadata?.full_name||user.user_metadata?.name||'Player';$('account-status').textContent='Loading your settings…';loading=true;$('save-dojos').disabled=true;$('save-profile').disabled=true;const profile=await supabase.from('profiles').select('display_name,game_id').eq('user_id',user.id).maybeSingle();if(profile.error)throw profile.error;if(id!==revision)return;if(profile.data){$('profile-name').value=profile.data.display_name;$('game-id').value=profile.data.game_id;}levels=await loadSettings();if(id!==revision)return;badgePickers();$('account-status').textContent='';$('save-dojos').disabled=false;$('save-profile').disabled=false;}catch(error){$('account-status').textContent='Account settings are unavailable. '+error.message;}finally{loading=false;}}
for(const provider of ['google','discord'])$(provider+'-login').onclick=async()=>{try{$('login-status').textContent='Opening '+provider+'…';await login(provider);}catch(error){$('login-status').textContent=error.message;}};
$('logout').onclick=async()=>{const {error}=await supabase.auth.signOut({scope:'local'});if(error){$('account-status').textContent=error.message;return;}await refresh();};
$('profile-form').onsubmit=async e=>{e.preventDefault();if(!user||loading)return;const displayName=$('profile-name').value.trim();if(!displayName){$('profile-status').textContent='Enter a display name.';return;}$('save-profile').disabled=true;try{const {error}=await supabase.from('profiles').upsert({user_id:user.id,display_name:displayName,game_id:$('game-id').value.trim()},{onConflict:'user_id'});if(error)throw error;$('profile-status').textContent='Profile saved.';}catch(error){$('profile-status').textContent=error.message;}finally{$('save-profile').disabled=false;}};
$('save-dojos').onclick=async()=>{if(loading)return;$('save-dojos').disabled=true;try{await saveSettings(levels);$('save-status').textContent='Dojo settings saved.';}catch(error){$('save-status').textContent=error.message;}finally{$('save-dojos').disabled=false;}};
supabase.auth.onAuthStateChange(()=>setTimeout(refresh,0));
try{const response=await fetch(new URL('roster.json',root));if(!response.ok)throw Error('Tatari assets could not load.');data=await response.json();badgePickers();await refresh();}catch(error){$('account-status').textContent=error.message;}
